declare(strict_types=1);

namespace Clavia\Domain\Webhook;

use Clavia\Domain\Shared\RandomSource;

/**
 * The secret an endpoint's deliveries are signed with (HMAC-SHA256), in the Standard Webhooks form:
 * `whsec_` and the base64 of 32 random bytes. Generated by this server, never chosen by an operator,
 * shown once (at registration and at rotation) and kept sealed: it must be read back to sign, so it
 * is encrypted, never hashed (docs/design/webhooks.md §2).
 *
 * Not printed by accident: no `__toString()`, nothing for `var_dump()` or `print_r()`, nothing in
 * `json_encode()`, and `#[\SensitiveParameter]` wherever it travels, so a stack trace holds none.
 * (`var_export()` reads private properties whatever a class says; nothing here calls it.)
 */
final readonly class WebhookSecret
{
    public const string PREFIX = 'whsec_';
    public const int KEY_BYTES = 32;

    /** @param non-empty-string $value */
    private function __construct(private string $value)
    {
    }

    public static function generate(RandomSource $random): self
    {
        return new self(self::PREFIX . base64_encode($random->bytes(self::KEY_BYTES)));
    }

    /**
     * A secret read back from its seal.
     *
     * @param non-empty-string $value
     */
    public static function unsealed(#[\SensitiveParameter] string $value): self
    {
        return new self($value);
    }

    /**
     * The secret itself, for the one answer that shows it and for sealing.
     *
     * @return non-empty-string
     */
    public function reveal(): string
    {
        return $this->value;
    }

    /** What the signature is computed with: the bytes after the prefix (Standard Webhooks). */
    public function key(): string
    {
        return (string) base64_decode(substr($this->value, strlen(self::PREFIX)), true);
    }

    /** @return array<string, string> Nothing of the secret, for a debugger or a log. */
    public function __debugInfo(): array
    {
        return ['value' => '(hidden)'];
    }
}
